function slicesUnderCap(nums: number[], k: number): number {
  let count = 0;
  for (let i = 0; i < nums.length; i++) {
    let prod = 1;
    for (let j = i; j < nums.length; j++) {
      prod *= nums[j];
      if (prod >= k) break;
      count++;
    }
  }
  return count;
}

